package com.yuegang.zhihui.knowledge.api;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.knowledge.application.KnowledgeLifecycleService;import com.yuegang.zhihui.knowledge.security.KnowledgeUserResolver;import jakarta.servlet.http.HttpServletRequest;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController public final class KnowledgeLifecycleController{private final KnowledgeLifecycleService service;private final KnowledgeUserResolver users;public KnowledgeLifecycleController(KnowledgeLifecycleService s,KnowledgeUserResolver u){service=s;users=u;}@GetMapping("/api/v1/knowledge/documents")ApiResponse<List<KnowledgeDocumentView>>publicList(@RequestParam(required=false)String category,@RequestParam(defaultValue="20")int limit,HttpServletRequest r){users.resolve(r,false);return ok(service.list(null,category,true,limit),r);}@GetMapping("/api/v1/admin/knowledge/documents")ApiResponse<List<KnowledgeDocumentView>>adminList(@RequestParam(required=false)String status,@RequestParam(required=false)String category,@RequestParam(defaultValue="50")int limit,HttpServletRequest r){users.resolve(r,true);return ok(service.list(status,category,false,limit),r);}@PutMapping("/api/v1/admin/knowledge/documents/{id}/offline")ApiResponse<KnowledgeDocumentView>offline(@PathVariable String id,@RequestParam long version,@RequestParam(required=false)String reason,HttpServletRequest r){return ok(service.offline(users.resolve(r,true),id,version,reason),r);}private static<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.success(x,TraceIdResolver.resolve(r));}}
